#[allow(unused_imports)]
use v1_compiled::\{v1_rt, NonEmptyBTreeSet, NonEmptyVec};
#[allow(unused_imports, dead_code)]
mod seed_std_logic;
use self::seed_std_logic as seed;

fn eq(e: emitted::Classical, s: seed::Classical) -> bool {
    matches!(
        (e, s),
        (emitted::Classical::True, seed::Classical::True)
            | (emitted::Classical::False, seed::Classical::False)
    )
}

fn main() {
    let inject_fault = std::env::args().any(|a| a == "--inject-fault");
    let vals = [emitted::Classical::True, emitted::Classical::False];
    let svals = [seed::Classical::True, seed::Classical::False];
    let mut all_pass = true;
    let mut cases = 0;

    for i in 0..2 {
        let call_on = if inject_fault && i == 0 { vals[1] } else { vals[i] };
        let er = emitted::classical_not(call_on);
        let sr = seed::classical_not(svals[i]);
        let ok = eq(er, sr);
        println!("not({:?}) emitted={:?} seed={:?} eq={}", vals[i], er, sr, ok);
        all_pass = all_pass && ok;
        cases += 1;
    }

    for i in 0..2 {
        for j in 0..2 {
            let er = emitted::classical_and(vals[i], vals[j]);
            let sr = seed::classical_and(svals[i], svals[j]);
            let ok = eq(er, sr);
            println!("and({:?},{:?}) emitted={:?} seed={:?} eq={}", vals[i], vals[j], er, sr, ok);
            all_pass = all_pass && ok;
            cases += 1;

            let er2 = emitted::classical_or(vals[i], vals[j]);
            let sr2 = seed::classical_or(svals[i], svals[j]);
            let ok2 = eq(er2, sr2);
            println!("or({:?},{:?}) emitted={:?} seed={:?} eq={}", vals[i], vals[j], er2, sr2, ok2);
            all_pass = all_pass && ok2;
            cases += 1;
        }
    }

    println!("SELF_HOST_LOGIC_CASES_COMPARED: {}", cases);

    if all_pass {
        println!("SELF_HOST_LOGIC_BEHAVIORAL_RECEIPT: PASS");
        std::process::exit(0);
    } else {
        println!("SELF_HOST_LOGIC_BEHAVIORAL_RECEIPT: FAIL");
        std::process::exit(1);
    }
}
"

